/* From Uiverse.io by Ratinax  - Tags:  */
.__UIV_SCOPE__ .radio-input {
  display: flex;
  scale: 0.15;
  transform: rotate(180deg);
}

.__UIV_SCOPE__ .star {
  margin: 1em;
  appearance: none;
  --color: white;
  border-left: 6.4721359549996em solid transparent;
  border-right: 6.4721359549996em solid transparent;
  border-bottom: 4em solid var(--color);
  transform: rotate(0deg);
  cursor: pointer;
}

.__UIV_SCOPE__ .star:before {
  content: "";
  border-left: 6.4721359549996em solid transparent;
  border-right: 6.4721359549996em solid transparent;
  border-top: 4em solid var(--color);
  position: absolute;
  left: -6.4721359549996em;
  transform: rotate(108deg);
}

.__UIV_SCOPE__ .star:after {
  content: "";
  border-left: 6.4721359549996em solid transparent;
  border-right: 6.4721359549996em solid transparent;
  border-top: 4em solid var(--color);
  position: absolute;
  left: -6.4721359549996em;
  transform: rotate(253deg);
}

.__UIV_SCOPE__ .radio-input > .star:hover ~ .star,
.__UIV_SCOPE__ .radio-input > .star:hover,
.__UIV_SCOPE__ .radio-input > .star:checked ~ .star,
.__UIV_SCOPE__ .radio-input > .star:checked {
  --color: yellow;
}

.__UIV_SCOPE__ .radio-input > .star:checked ~ .star,
.__UIV_SCOPE__ .radio-input > .star:checked {
  animation: rotate 0.5s linear forwards;
  transform: rotate(360deg);
  transition: transform 0.3s;
}

@keyframes rotate {
  0% {
    transform: rotate(0deg);
  }
  50% {
    scale: 1.5;
  }
  100% {
    transform: rotate(360deg);
  }
}
